// ==UserScript==
// @name         Baper Rasta — Bongobondhu Mode (God Mode)
// @namespace    baperrasta-mod
// @version      1.8.2
// @author       Jafran Hasan (@jafranonline)
// @homepageURL  https://www.facebook.com/jafranonline/
// @updateURL    https://raw.githubusercontent.com/jafranonline/baperrasta-mod/main/baperrasta-mod.user.js
// @downloadURL  https://raw.githubusercontent.com/jafranonline/baperrasta-mod/main/baperrasta-mod.user.js
// @description  Official Bongobondhu Mode by Jafran Hasan (@jafranonline, https://www.facebook.com/jafranonline/). Patches baperrasta.com's game module: battery locked at 100%, no crash battery penalty, speed multiplier, Fly Mode (hold F), no bus/hole/mob death, and Most Wanted leaderboard sync.
// @match        https://baperrasta.com/*
// @match        https://*.baperrasta.com/*
// @run-at       document-start
// @inject-into  page
// @grant        none
// ==/UserScript==

(() => {
  'use strict';

  const CFG = {
    battery100: true,     // charge always 1.0, never pedal mode
    noCrashDrain: true,   // crashes into vehicles/walls cost no battery
    speedMult: 3.0,       // cruise/boost/acceleration multiplier ([ and ] change it live)
    invincible: true,     // no mob bust, grabbers can't slow you
    noBusDeath: true,     // buses/trucks shove you aside like normal cars instead of killing you
    keepMoney: true,      // paying police "চা-পানি" no longer subtracts from your ৳ score
    pointsMult: 10,       // ৳ earned per crash, near miss and jump is multiplied by this
    busPoints: true,      // ramming a bus/truck wrecks it for ৳ like any other vehicle (needs noBusDeath)
    posterText: 'বঙ্গবল্টু মরেনাই', // replaces "সুপারহিট!" on the board at the rickshaw's back ('' keeps the original)
    posterTitle: 'বঙ্গবল্টু',       // replaces the "বাপের রাস্তা" movie title on the rickshaw's canopy ('' keeps the original)
    gameName: '',         // replaces "বাপের রাস্তা" everywhere else: menu, loading, tab title, newspaper, share ('' keeps it)
    gameNameEn: '',       // replaces "Baper Rasta" (menu subtitle, tab title)
    savedSound: true,     // play bongoboltu.mp3 with the "বঙ্গবল্টু মরেনাই" toast (silent when the game's sound is off)
    savedSoundGap: 15,    // seconds between plays, so constant crashing doesn't loop it
    endSound: true,       // play zodi-rat.mp3 when you end the run yourself (K / Esc); same mute rules
  };

  const MODE_NAME = 'Bongobondhu Mode';
  const CREDIT = 'Jafran Hasan (@jafranonline)';
  const CREDIT_URL = 'https://www.facebook.com/jafranonline/';
  const GAME_CREDIT = 'Omar Faruqe Riyad';
  const GAME_CREDIT_URL = 'https://baperrasta.com/about.html';
  const creditLink = (text, href) => `<a href="${href}" target="_blank" rel="noopener" style="color:inherit;text-decoration:underline;pointer-events:auto">${text}</a>`;
  const CREDIT_HTML = `${MODE_NAME} by ${creditLink(CREDIT, CREDIT_URL)} · game by ${creditLink(GAME_CREDIT, GAME_CREDIT_URL)}`;
  const onReady = (fn) => document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', fn, { once: true }) : fn();

  // --- About page (/about, /about.html): add the mode's credit below the maker's links, in the page's own styles ---
  if (/^\/about(\.html)?\/?$/.test(location.pathname)) {
    onReady(() => {
      const main = document.querySelector('main');
      if (!main || main.querySelector('[data-br]')) return;
      const sec = document.createElement('section');
      sec.dataset.br = '';
      sec.setAttribute('aria-label', MODE_NAME);
      sec.innerHTML = `
        <p class="kicker">${MODE_NAME}</p>
        <p class="role">God Mode for <span lang="bn">বাপের রাস্তা</span>, by <b>${CREDIT}</b>.
          Full battery, no bus death, mob-proof, speed control<p>
        <ul class="links" style="margin-top:10px">
          <li><a href="${CREDIT_URL}" rel="noopener"><b>Facebook</b><span>Jafran Hasan · @jafranonline</span></a></li>
        </ul>`;
      main.insertBefore(sec, main.querySelector('.back'));
    });
    return; // no game on this page
  }

  // --- Home menu: "Bongobondhu Mode" badge under the game title ---
  function addMenuBadge() {
    const title = document.querySelector('#menu .title');
    if (!title || document.getElementById('br-badge')) return;
    const style = document.createElement('style');
    style.textContent = `
      #br-badge{display:inline-flex;flex-wrap:wrap;align-items:center;gap:4px 8px;margin:8px 0 2px;padding:4px 12px 3px;
        border-radius:999px;background:#ffd400;border:2px solid #c8102e;box-shadow:0 3px 0 #7a0a1c;color:#16302a;
        font-size:13px;font-weight:700;line-height:1.3}
      #br-badge b{color:#c8102e;font-size:15px;font-weight:800}
      #br-badge a{color:inherit;text-decoration:underline;text-underline-offset:2px}`;
    document.head.appendChild(style);
    const badge = document.createElement('div');
    badge.id = 'br-badge';
    badge.innerHTML = `<b>⚡ ${MODE_NAME}</b><span>God Mode by <a href="${CREDIT_URL}" target="_blank" rel="noopener">${CREDIT}</a></span>`;
    title.parentElement.after(badge);
  }
  onReady(addMenuBadge);

  // Read by the patched game code
  window.__BR_noBusDeath = CFG.noBusDeath;
  window.__BR_keepMoney = CFG.keepMoney;
  window.__BR_pointsK = CFG.pointsMult;

  const TAG = `[${MODE_NAME}]`;
  const log = (...a) => console.log(`%c${TAG}`, 'color:#4dff95;font-weight:bold', ...a);
  const warn = (...a) => console.warn(TAG, ...a);

  // Cheat keys as shown in the game's help: [keys, label, short label for the menu]
  const CHEAT_KEYS = [
    [['F'], 'ধরে রাখলে সামনে উড়বে, ছাড়লে নামবে', 'ফ্লাই (ধরে রাখুন)'],
    [['Z'], 'মব হটান', 'মব হটান'],
    [['Shift', 'Z'], 'অটো মব হটানো চালু/বন্ধ', 'অটো মব'],
    [['K', 'Esc'], 'খেলা শেষ, স্কোর দেখুন', 'খেলা শেষ'],
    [['[', ']'], 'স্পিড কম/বেশি', 'স্পিড'],
    [['P'], 'পজ / আবার চালান', 'পজ'],
  ];

  // --- Source patches (regexes tolerate renamed minified identifiers) ---
  const PATCHES = [
    // window.__at is normally only set with ?debug AND navigator.webdriver on the live domain
    { name: 'expose __at', re: /[\w$]+\(\)&&\(window\.__at=/, to: '(window.__at=' },
    // speed table {cruise,boost,pedal,acc,accBoost,accPedal,brake}
    { name: 'speed table', re: /([\w$]+)=\{cruise:/, to: '$1=window.__BR_speed={cruise:' },
    // crash battery penalty {vehicle,wall}
    { name: 'crash table', re: /([\w$]+)=\{vehicle:/, to: '$1=window.__BR_crash={vehicle:' },
    // bus/truck hit: hand the bus and impact speed to the mod instead of killing, then fall through to the normal push-out
    {
      name: 'bus death',
      re: /if\(([\w$]+\.state==="play"&&\(([\w$]+)>[^)]*\))\)\{([\w$]+\.kill\("bus",([\w$]+)\);return)\}/,
      to: 'if($1){if(window.__BR_noBusDeath)window.__BR_onBusHit&&window.__BR_onBusHit($4,$2);else{$3}}',
    },
    // pothole / manhole fall death bypass
    {
      name: 'hole death',
      re: /([\w$]+)\.fall\(([\w$]+\.man\?"manhole":"pothole"),([\w$]+)\);return/,
      to: 'if(!window.__BR_noBusDeath){$1.fall($2,$3);return}',
    },
    // per-vehicle ৳ table {car,suv,...}; buses/trucks get entries at runtime
    { name: 'points table', re: /([\w$]+)=(\{car:[\d.e]+,suv:)/, to: '$1=window.__BR_points=$2' },
    // floater captions per vehicle {mirror:"সাইড মিরর!",...}
    { name: 'points labels', re: /([\w$]+)=\{mirror:"/, to: '$1=window.__BR_labels={mirror:"' },
    // ৳ multiplier: crash award, near miss, jump
    {
      name: 'points crash',
      re: /([\w$]+=)(Math\.max\(50,Math\.round\([\w$]+\[[\w$]+\]\*[\w$]+\([^)]*\)\*[\w$]+\/50\)\*50\))/,
      to: '$1$2*(window.__BR_pointsK||1)',
    },
    { name: 'points near miss', re: /([\w$]+)\.nearbus\*Math\.max\(1,this\.combo\)/, to: '$1.nearbus*(window.__BR_pointsK||1)*Math.max(1,this.combo)' },
    { name: 'points jump', re: /([\w$]+)=3e3,([\w$]+=\{first:)/, to: '$1=3e3*(window.__BR_pointsK||1),$2' },
    // bribe payment is the only thing that lowers the ৳ score
    { name: 'keep money', re: /([\w$]+)\.loss-=([\w$]+)/, to: '$1.loss-=window.__BR_keepMoney?0:$2' },
    // rickshaw movie-poster art (only the poster calls the s(r,"...") text helper with these)
    ...(CFG.posterText ? [{ name: 'poster text', re: /"সুপারহিট!?"/, to: JSON.stringify(CFG.posterText) }] : []),
    ...(CFG.posterTitle ? [{ name: 'poster title', re: /([\w$]+\([\w$]+,)"বাপের রাস্তা"(,[\w$]+\/2,118,)/, to: `$1${JSON.stringify(CFG.posterTitle)}$2` }] : []),
    // game name in newspaper logo, meme card, clip overlay, share title (must run after 'poster title')
    ...(CFG.gameName ? [{ name: 'game name', re: /বাপের রাস্তা/g, to: CFG.gameName }] : []),
    // in-run "কীভাবে চালাবেন" card: append our cheat keys using the game's own row helper
    {
      name: 'controls card',
      re: /([\w$]+)\(\["M"\],"শব্দ"\)/,
      to: (m, row) => m + `+'<span class="t">${CREDIT_HTML}</span>'` +
        CHEAT_KEYS.map(([keys, label]) => `+${row}(${JSON.stringify(keys)},${JSON.stringify(label)})`).join(''),
    },
    // camera: distance/height/FOV grow with speed and follow smoothing is fixed, so at high
    // speed the rickshaw runs away from the camera. Feed it speed / multiplier and scale the
    // smoothing by the multiplier so framing matches stock speed.
    {
      name: 'camera follow',
      re: /camera\([\w$]+\)\{let [\w$]+=this\.portrait[\s\S]*?updateProjectionMatrix\(\)/,
      to: (body) => body
        .replace(/Math\.abs\(([\w$]+)\.v\)/g, '(Math.abs($1.v)/(window.__BR_camK||1))')
        .replace(/(this\.state==="play"\?)7:/, '$17*(window.__BR_camK||1):')
        .replace(/([\w$]+\([\w$]+\.x,[\w$]+\.z\)\.block)/, '(!window.__BR_flying&&$1)'),
    },
  ];

  function patchSource(src) {
    for (const p of PATCHES) {
      p.re.lastIndex = 0;
      if (p.re.test(src)) src = src.replace(p.re, p.to);
      else warn(`patch "${p.name}" did not match — game may have updated`);
    }
    return src;
  }

  // Fallback if the __at patch stops matching: satisfy the game's own debug check
  function enableDebugFallback() {
    try {
      Object.defineProperty(Navigator.prototype, 'webdriver', { configurable: true, get: () => true });
      const u = new URL(location.href);
      if (!u.searchParams.has('debug')) {
        u.searchParams.set('debug', '');
        history.replaceState(history.state, '', u.pathname + u.search + u.hash);
      }
    } catch (e) { warn('debug fallback failed', e); }
  }

  async function loadPatched(src) {
    let code;
    try {
      code = await (await fetch(src, { credentials: 'same-origin' })).text();
    } catch (e) {
      warn('could not fetch game script, loading original', e);
      return inject({ src });
    }
    if (!PATCHES[0].re.test(code)) enableDebugFallback();
    inject({ text: patchSource(code) + `\n//# sourceURL=${src}` });
  }

  function inject({ src, text }) {
    const run = () => {
      const s = document.createElement('script');
      s.type = 'module';
      if (src) s.src = src; else s.textContent = text;
      (document.head || document.documentElement).appendChild(s);
    };
    document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', run, { once: true }) : run();
  }

  // --- Rename the game in the static page (menu title, loading screen, tab title, labels) ---
  function renamePage() {
    const swaps = [['বাপের রাস্তা', CFG.gameName], ['Baper Rasta', CFG.gameNameEn]].filter(([, to]) => to);
    const swap = (s) => swaps.reduce((acc, [from, to]) => acc.split(from).join(to), s);
    document.title = swap(document.title);
    const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    for (let n; (n = walker.nextNode());) {
      if (swaps.some(([from]) => n.nodeValue.includes(from))) n.nodeValue = swap(n.nodeValue);
    }
    for (const el of document.querySelectorAll('[title],[aria-label],[alt]')) {
      for (const a of ['title', 'aria-label', 'alt']) {
        const v = el.getAttribute(a);
        if (v && swaps.some(([from]) => v.includes(from))) el.setAttribute(a, swap(v));
      }
    }
  }
  if (CFG.gameName || CFG.gameNameEn) {
    document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', renamePage, { once: true }) : renamePage();
  }

  // --- Block the original game module before the parser runs it ---
  const isGame = (n) => n.tagName === 'SCRIPT' && /\/game\.[\w-]+\.js(\?|$)/.test(n.src || '');
  let hijacked = false;
  const mo = new MutationObserver((muts) => {
    for (const m of muts) for (const n of m.addedNodes) {
      if (hijacked || !isGame(n)) continue;
      hijacked = true;
      const src = n.src;
      n.type = 'javascript/blocked';
      n.remove();
      mo.disconnect();
      loadPatched(src);
    }
  });
  mo.observe(document, { childList: true, subtree: true });

  // --- Leaderboard score submission: normalize stats & token age so /api/score accepts modded runs ---
  const TOKEN_POOL_KEY = 'baperRasta.runTokens';
  const USED_TOKENS_KEY = 'baperRasta.usedTokens';
  const MAX_TOKEN_AGE = 21600; // 6 hours (server tokens remain valid well past 90+ minutes)
  const SEED_TOKENS = [
    'mvqeod21.d0b4ef0f8c0e4184.xLxMsBpdCKJhRt9kDYOqgX79FE_3ad03hHdmF2mrpdg',
    'mvqeod2n.7ef755a7b6d440ae.vB4lzYSYFZx9XEmyx8AjhvvycZB2IymfK8SsJfmWNx8',
    'mvqg4gi5.b00f261dea0b4d24.Y9dTrRnWZiGq9_S-k0kq4E9kutkqYtn14CyOBCQiUUU',
    'mvqg4hoq.45335c839fc34700.G7ESJbulWx2mCVMlNJfrLdjGgrNGHF4RkU086gjwNRI',
    'mvqg4iv3.8096c4cca1cf4fa2.m88RaD07KAtyiaOQnDI_TFFgV0RA_o0CevammTP1TH8',
    'mvqg4k1f.3c6e8d36994448df.QizTU4OUxLw6_6h-TWXDnyOcHqEaPVW6_kHj-cdz7wY',
    'mvqg4l7s.a11f1bdf4f75441f.bpi4EheTYcMfy7aGaIb-BY2skFK_9VorxiN_xBAvyKk',
    'mvqg4me3.a78095e315934973.pK0KQ0R-RS2dwpe0hWTuF6XgnFw7ssMJn-Ph_c_PFis',
  ];

  function tokenAgeSecs(t) {
    if (typeof t !== 'string' || !t.includes('.')) return -1;
    const ms = parseInt(t.split('.')[0], 36);
    return Number.isFinite(ms) ? Math.floor((Date.now() - ms) / 1000) : -1;
  }

  // Server ranked curves: loss/crashes <= 40000, crashes <= 20 + 0.7*secs, loss <= 500000 + 12000*secs
  function statsForLoss(rawLoss) {
    const loss = Math.max(50, Math.round((rawLoss || 0) / 50) * 50);
    const crashes = Math.max(2, Math.ceil(loss / 36000));
    const neededSecs = Math.max(
      6,
      Math.ceil(Math.max(0, loss - 350000) / 11500),
      Math.ceil(Math.max(0, crashes - 15) / 0.6)
    );
    return { loss, crashes, neededSecs };
  }

  function maxLossForSecs(secs) {
    const s = Math.max(6, secs);
    const byTime = 350000 + 11500 * s;
    const byCrashes = Math.floor(15 + 0.6 * s) * 36000;
    return Math.floor(Math.min(byTime, byCrashes) / 50) * 50;
  }

  function getUsedTokens() {
    try { return new Set(JSON.parse(localStorage.getItem(USED_TOKENS_KEY) || '[]')); } catch { return new Set(); }
  }

  function getTokenPool() {
    let list = [];
    try {
      list = JSON.parse(localStorage.getItem(TOKEN_POOL_KEY) || '[]');
      const legacy = localStorage.getItem('baperRasta.runToken');
      if (legacy) list.push(legacy);
    } catch {}
    const used = getUsedTokens();
    const seen = new Set();
    const valid = [...SEED_TOKENS, ...list].filter((t) => {
      if (!t || seen.has(t) || used.has(t)) return false;
      seen.add(t);
      const age = tokenAgeSecs(t);
      return age >= 0 && age < MAX_TOKEN_AGE;
    });
    // Sort oldest first (largest age first)
    valid.sort((a, b) => tokenAgeSecs(b) - tokenAgeSecs(a));
    try { localStorage.setItem(TOKEN_POOL_KEY, JSON.stringify(valid.slice(0, 16))); } catch {}
    return valid;
  }

  function addTokenToPool(t) {
    if (!t || getUsedTokens().has(t)) return;
    const pool = getTokenPool();
    if (!pool.includes(t)) {
      pool.push(t);
      try { localStorage.setItem(TOKEN_POOL_KEY, JSON.stringify(pool.slice(0, 16))); } catch {}
    }
  }

  function dropTokenFromPool(t) {
    const idx = SEED_TOKENS.indexOf(t);
    if (idx !== -1) SEED_TOKENS.splice(idx, 1);
    try {
      const used = getUsedTokens();
      used.add(t);
      localStorage.setItem(USED_TOKENS_KEY, JSON.stringify([...used].slice(-40)));
      const list = JSON.parse(localStorage.getItem(TOKEN_POOL_KEY) || '[]').filter((x) => x !== t);
      localStorage.setItem(TOKEN_POOL_KEY, JSON.stringify(list));
      if (localStorage.getItem('baperRasta.runToken') === t) localStorage.removeItem('baperRasta.runToken');
    } catch {}
  }

  // Clear any unranked best saved earlier when /api/score was blocked or rejected, so Mo.end doesn't skip submitting
  function clearUnrankedBest() {
    try {
      const cur = JSON.parse(localStorage.getItem('baperRasta.wanted') || 'null');
      if (cur && !cur.rank && cur.best > 0) {
        localStorage.setItem('baperRasta.wanted', JSON.stringify({ ...cur, best: 0 }));
      }
    } catch {}
  }
  clearUnrankedBest();

  const origFetch = window.fetch;

  function warmRunToken() {
    try {
      const pool = getTokenPool();
      const recentCount = pool.filter((t) => tokenAgeSecs(t) < 900).length;
      if (recentCount >= 3) return;
      origFetch('api/run', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          device: localStorage.getItem('baperRasta.device') || '',
          pass: localStorage.getItem('baperRasta.devicePass') || '',
        }),
      }).then((r) => r.json()).then((d) => {
        if (d?.t) addTokenToPool(d.t);
        if (d?.device && !localStorage.getItem('baperRasta.device')) localStorage.setItem('baperRasta.device', d.device);
        if (d?.pass && !localStorage.getItem('baperRasta.devicePass')) localStorage.setItem('baperRasta.devicePass', d.pass);
      }).catch(() => {});
    } catch {}
  }
  warmRunToken();
  setInterval(warmRunToken, 180000);

  async function sendScoreWithToken(input, init, body, useT, rawLoss) {
    const elapsed = Math.max(0, tokenAgeSecs(useT));
    // Never wait more than 2 seconds: cap loss to what this token's age can validate right now
    const maxAllowedLoss = maxLossForSecs(elapsed + 2);
    const { loss, crashes, neededSecs } = statsForLoss(Math.min(rawLoss, maxAllowedLoss));
    if (elapsed < neededSecs) {
      const waitMs = Math.min(2500, (neededSecs - elapsed) * 1000);
      if (waitMs > 0) await new Promise((r) => setTimeout(r, waitMs));
    }
    return origFetch(input, {
      ...init,
      body: JSON.stringify({ ...body, t: useT, loss, crashes, secs: neededSecs }),
    });
  }

  window.fetch = async function (input, init) {
    const url = typeof input === 'string' ? input : input?.url || '';
    if (/(^|\/)api\/run(\?|$)/.test(url)) {
      const res = await origFetch.apply(this, arguments);
      res.clone().json().then((d) => { if (d?.t) addTokenToPool(d.t); }).catch(() => {});
      return res;
    }
    if (/(^|\/)api\/score(\?|$)/.test(url)) {
      try {
        clearUnrankedBest();
        const body = JSON.parse(init?.body || '{}');
        if (body.t) addTokenToPool(body.t);
        const { loss, neededSecs } = statsForLoss(body.loss);
        const pool = getTokenPool();
        if (body.t && !pool.includes(body.t)) pool.push(body.t);

        let prevBest = 0;
        try {
          const cur = JSON.parse(localStorage.getItem('baperRasta.wanted') || 'null');
          if (cur?.rank && cur.best > 0) prevBest = cur.best;
        } catch {}

        // Pick the YOUNGEST token that already satisfies neededSecs (so older tokens stay saved for bigger scores),
        // followed by remaining tokens from oldest to youngest that can at least beat prevBest.
        const ready = pool.filter((t) => tokenAgeSecs(t) + 2 >= neededSecs).sort((a, b) => tokenAgeSecs(a) - tokenAgeSecs(b));
        const notReady = pool
          .filter((t) => tokenAgeSecs(t) + 2 < neededSecs && maxLossForSecs(tokenAgeSecs(t) + 2) > prevBest)
          .sort((a, b) => tokenAgeSecs(b) - tokenAgeSecs(a));
        const candidates = [...ready, ...notReady];
        if (!candidates.length && pool.length) candidates.push(pool[0]);

        let lastRes = null;
        for (const cand of candidates) {
          lastRes = await sendScoreWithToken(input, init, body, cand, loss);
          const data = await lastRes.clone().json().catch(() => null);
          if (data && data.best > 0) {
            if (data.rank) dropTokenFromPool(cand); // server only consumes token on ranked submissions
            warmRunToken();
            log(`score accepted: ৳${data.best} (rank: ${data.rank ?? 'unranked'})`);
            return lastRes;
          }
          if (data?.error === 'used' || data?.error === 'expired' || lastRes.status === 409) {
            dropTokenFromPool(cand);
          }
        }
        return lastRes || origFetch.apply(this, arguments);
      } catch (e) {
        warn('score normalization failed, sending original', e);
      }
    }
    return origFetch.apply(this, arguments);
  };

  // --- Runtime mods, applied once the game exposes window.__at ---
  const SPEED_KEYS = ['cruise', 'boost', 'pedal', 'acc', 'accBoost', 'accPedal'];
  let speedBase = null;

  function setSpeed(mult) {
    const t = window.__BR_speed;
    if (!t) return;
    if (!speedBase) speedBase = Object.fromEntries(SPEED_KEYS.map((k) => [k, t[k]]));
    CFG.speedMult = Math.max(0.5, Math.min(8, Math.round(mult * 10) / 10));
    for (const k of SPEED_KEYS) t[k] = speedBase[k] * CFG.speedMult;
    window.__BR_camK = Math.max(1, CFG.speedMult);
    window.__at?.MSG?.show?.('hint', `⚡ স্পিড x${CFG.speedMult}`, 1.5, 0);
  }

  let origKill = null;

  // --- "Would have died" toast ---
  const SAVED_SUB = {
    bus: 'বাসের ধাক্কা খেয়েও!',
    mob: 'পাবলিকের হাত থেকে বেঁচে গেলেন!',
    pothole: 'গর্তে পড়েও!',
    manhole: 'খোলা ম্যানহোলে পড়েও!',
  };
  let toastEl = null;
  let toastHideT = 0;
  let lastToastAt = -Infinity;
  let savedAudio = null;
  let lastSoundAt = -Infinity;

  // the game's own sound switch (M key / speaker button); fall back to the button if sfx isn't exposed
  const gameMuted = () => window.__at?.sfx?.muted ?? !!document.querySelector('#muteBtn.off');

  function playSavedSound() {
    if (!CFG.savedSound || gameMuted() || document.hidden) return;
    const now = performance.now();
    if (now - lastSoundAt < CFG.savedSoundGap * 1000) return;
    if (savedAudio && !savedAudio.paused) return; // never cut itself off
    lastSoundAt = now;
    savedAudio ||= new Audio(BONGOBOLTU_MP3);
    savedAudio.currentTime = 0;
    savedAudio.play().catch(() => {}); // blocked until the first user gesture; harmless
  }

  let endAudio = null;

  function playEndSound() {
    if (!CFG.endSound || gameMuted() || document.hidden) return;
    stopSavedSound(); // don't talk over it
    endAudio ||= new Audio(ZODI_RAT_MP3);
    endAudio.currentTime = 0;
    endAudio.play().catch(() => {});
    // a new run (R / play again) cuts it off; endRun only fires from 'play', so wait for it to leave first
    let left = false;
    const watch = setInterval(() => {
      if (endAudio.paused) return clearInterval(watch);
      const playing = window.__at?.G?.state === 'play';
      if (!playing) left = true;
      else if (left) { endAudio.pause(); clearInterval(watch); }
    }, 150);
  }

  function stopSavedSound() {
    if (savedAudio && !savedAudio.paused) savedAudio.pause();
  }
  function stopAllSounds() {
    stopSavedSound();
    if (endAudio && !endAudio.paused) endAudio.pause();
  }
  document.addEventListener('visibilitychange', () => { if (document.hidden) stopAllSounds(); });

  function savedToast(cause) {
    const now = performance.now();
    if (now - lastToastAt < 2500) return; // a bus scrape fires every frame
    lastToastAt = now;

    if (!toastEl) {
      const style = document.createElement('style');
      style.textContent = `
        #br-saved{position:fixed;left:50%;top:16%;z-index:99999;pointer-events:none;text-align:center;
          transform:translate(-50%,-20px) scale(.6);opacity:0;transition:transform .35s cubic-bezier(.2,1.6,.4,1),opacity .25s;
          padding:12px 26px 10px;border-radius:16px;background:#ffd400;border:4px solid #c8102e;
          box-shadow:0 6px 0 #7a0a1c,0 10px 28px rgba(0,0,0,.45);font-family:"Baloo Da 2","Anek Bangla",sans-serif}
        #br-saved.show{transform:translate(-50%,0) scale(1);opacity:1}
        #br-saved b{display:block;font-size:clamp(26px,5vw,44px);font-weight:800;line-height:1.1;color:#c8102e;
          text-shadow:2px 2px 0 #fff}
        #br-saved span{display:block;margin-top:2px;font-size:clamp(13px,2.2vw,18px);font-weight:700;color:#16302a}`;
      document.head.appendChild(style);
      toastEl = document.createElement('div');
      toastEl.id = 'br-saved';
      toastEl.innerHTML = '<b>বঙ্গবল্টু মরেনাই 💪</b><span></span>';
      document.body.appendChild(toastEl);
    }
    toastEl.querySelector('span').textContent = SAVED_SUB[cause] || '';
    toastEl.classList.remove('show');
    void toastEl.offsetWidth; // restart the pop animation
    toastEl.classList.add('show');
    clearTimeout(toastHideT);
    toastHideT = setTimeout(() => toastEl.classList.remove('show'), 2200);
    window.__at?.FX?.shake?.(0.25);
    playSavedSound();
  }
  window.__BR_onSaved = (cause) => { if (window.__at?.G?.state === 'play') savedToast(cause); };

  // Bus/truck contact (only reached with noBusDeath). The game has no crash/score path for
  // "killer" vehicles, so award one like a normal wreck, once per ram rather than every frame.
  const busHitAt = new WeakMap();
  window.__BR_onBusHit = (bus, impact) => {
    window.__BR_onSaved('bus');
    const at = window.__at;
    if (!CFG.busPoints || at?.G?.state !== 'play' || !(impact > 1.6) || !window.__BR_points?.[bus.kind]) return;
    const now = performance.now();
    if (now - (busHitAt.get(bus) ?? -Infinity) < 1500) return;
    busHitAt.set(bus, now);
    at.TRAFFIC?.wreck?.(bus, impact, 0, 0, false, bus.x, bus.z); // killer kinds: crash sound only
    at.G.award(bus.kind, impact, bus.x, bus.z, {});
    at.FX?.shake?.(Math.min(0.5, 0.15 + impact / 16));
  };

  // Menu screen key list (#keysHelp is static HTML: <span class="k"><kbd>W</kbd> চালান</span>…)
  function addMenuKeys() {
    const box = document.getElementById('keysHelp');
    if (!box || box.querySelector('[data-br]')) return;
    for (const [keys, , short] of CHEAT_KEYS) {
      const item = document.createElement('span');
      item.className = 'k';
      item.dataset.br = '';
      for (const k of keys) item.appendChild(document.createElement('kbd')).textContent = k;
      item.append(' ' + short);
      box.appendChild(item);
    }
    const credit = document.createElement('span');
    credit.className = 'k';
    credit.dataset.br = '';
    credit.innerHTML = `⚡ ${CREDIT_HTML}`;
    box.appendChild(credit);
  }

  // Grabbers are locked to 0 so the game never busts; replay its bust rule on the real grab count
  function watchMob(at) {
    let stuckT = 0;
    let last = performance.now();
    setInterval(() => {
      const now = performance.now();
      const dt = (now - last) / 1000;
      last = now;
      const n = at.PEOPLE?.grabbing || 0;
      if (at.G.state !== 'play' || n === 0) { stuckT = 0; return; }
      if (Math.abs(at.P.v) < 0.9) stuckT += dt; else stuckT = Math.max(0, stuckT - dt);
      if (n >= 3 || stuckT > (n >= 2 ? 1 : 1.8)) { stuckT = 0; savedToast('mob'); }
    }, 100);
  }

  // Periodically save personal best and auto-submit to /api/score in the background during a run
  function watchScore(at) {
    let syncing = false;
    let lastSyncedLoss = 0;
    let lastSyncAt = 0;
    let fetchedBoardCut = false;

    setInterval(async () => {
      const { G, WANTED } = at;
      if (!G || G.state !== 'play') {
        if (G?.state === 'menu') lastSyncedLoss = 0;
        return;
      }

      const rawLoss = Math.floor((G.loss || 0) / 50) * 50;
      if (rawLoss < 50) return;

      // Keep local personal best updated live even if the tab is closed before pressing K/Esc
      if (rawLoss > (G.best || 0)) {
        G.best = rawLoss;
        try { localStorage.setItem('baperRasta.best', String(rawLoss)); } catch {}
      }

      if (!WANTED?.on || syncing) return;
      const now = performance.now();
      if (now - lastSyncAt < 25000) return;

      const week = WANTED.weekOf ? WANTED.weekOf(Date.now()) : '';
      let cut = week && WANTED.cutOf ? WANTED.cutOf(week) : 0;
      if (!cut && !fetchedBoardCut) {
        fetchedBoardCut = true;
        try {
          const b = await (await origFetch('api/board')).json();
          if (b?.ok && b.week && Number.isFinite(b.cut)) {
            WANTED.keepCut?.(b.week, b.cut);
            cut = b.cut;
          }
        } catch {}
      }

      const mine = week && WANTED.mine ? WANTED.mine(week) : { best: 0, rank: null };
      const prevBest = mine?.rank ? (mine.best || 0) : 0;

      const pool = getTokenPool();
      // Only background-sync when we have at least 2 tokens capable of beating prevBest,
      // keeping the single oldest token in reserve for when the player ends the run (K/Esc).
      const viable = pool.filter((t) => maxLossForSecs(tokenAgeSecs(t) + 2) > Math.max(cut, prevBest));
      if (viable.length < 2) return;
      const bgToken = viable[1];
      const maxAge = Math.max(6, tokenAgeSecs(bgToken));
      const maxInstantLoss = maxLossForSecs(maxAge + 2);
      const sendLoss = Math.min(rawLoss, maxInstantLoss);

      if (sendLoss <= cut || sendLoss <= prevBest || (lastSyncedLoss > 0 && sendLoss - lastSyncedLoss < 2000000)) return;

      syncing = true;
      lastSyncAt = now;
      try {
        const ident = WANTED.ident ? WANTED.ident() : {
          device: localStorage.getItem('baperRasta.device') || '',
          pass: localStorage.getItem('baperRasta.devicePass') || '',
        };
        const res = await window.fetch('api/score', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            t: WANTED.token || bgToken,
            ...ident,
            loss: sendLoss,
            crashes: G.crashes || 2,
            secs: Math.max(6, Math.round(G.runT || 6)),
          }),
        });
        const data = await res.json().catch(() => null);
        if (data?.ok && data.best > 0) {
          lastSyncedLoss = data.best;
          WANTED.adopt?.(data);
          WANTED.keepCut?.(data.week, data.cut);
          try {
            localStorage.setItem('baperRasta.wanted', JSON.stringify({
              week: data.week,
              best: data.best,
              rank: data.rank,
              need: data.need,
              on: !!data.rank || (mine?.week === data.week && mine?.on !== false),
            }));
          } catch {}
          WANTED.stale = true;
          WANTED.rank = data.rank;
          const bDT = data.best.toLocaleString('en-IN');
          at.MSG?.show?.('hint', data.rank ? `🏆 মোস্ট ওয়ান্টেড #${data.rank} · ৳${bDT}` : `📈 স্কোর সেভ হয়েছে: ৳${bDT}`, 2.5, 0);
        }
      } catch (e) {
        warn('live score sync failed', e);
      } finally {
        syncing = false;
      }
    }, 5000);
  }

  function lockProp(obj, key, value) {
    Object.defineProperty(obj, key, { configurable: true, enumerable: true, get: () => value, set() {} });
  }

  function applyMods(at) {
    const { P, G } = at;

    if (CFG.battery100) {
      lockProp(P, 'charge', 1);
      lockProp(P, 'pedal', false);
    }

    if (CFG.noCrashDrain && window.__BR_crash) {
      window.__BR_crash.vehicle = 0;
      window.__BR_crash.wall = 0;
    }

    setSpeed(CFG.speedMult);

    if (CFG.busPoints && window.__BR_points) {
      Object.assign(window.__BR_points, { bus: 3000, truck: 2500 }); // before pointsMult, like the stock values
      if (window.__BR_labels) Object.assign(window.__BR_labels, { bus: 'বাস ধোলাই!', truck: 'ট্রাক ধোলাই!' });
    }

    origKill = G.kill; // kept for the K (end run) cheat
    if (CFG.noBusDeath) G.kill = function () {}; // only cause the game uses is "bus" (buses & trucks)
    if (CFG.invincible || CFG.noBusDeath) {
      G.fall = function (cause) { savedToast(cause || 'pothole'); }; // potholes & open manholes
      if (at.HOLES) {
        at.HOLES.hit = function (hole, front, speed) {
          if (hole) hole.hitT = G.t;
          P.bumpY = hole?.man ? 0.14 : 0.08;
          at.sfx?.bump?.();
          if (front && (hole?.man || speed >= 9 || P.boost)) {
            savedToast(hole?.man ? 'manhole' : 'pothole');
          }
        };
      }
    }

    // Ensure Mo.end still runs its full newspaper UI & name-input flow even if watchScore already synced this run's score
    if (G.showPaper) {
      const origShowPaper = G.showPaper;
      G.showPaper = function () {
        try {
          const cur = JSON.parse(localStorage.getItem('baperRasta.wanted') || 'null');
          const runLoss = Math.round(this.loss || 0);
          if (cur && !cur.rank && cur.best > 0) {
            localStorage.setItem('baperRasta.wanted', JSON.stringify({ ...cur, best: 0 }));
          } else if (cur && cur.rank && runLoss >= cur.best) {
            localStorage.setItem('baperRasta.wanted', JSON.stringify({
              ...cur,
              best: Math.max(0, runLoss - 50),
            }));
          }
        } catch {}
        return origShowPaper.apply(this, arguments);
      };
    }

    if (CFG.invincible) {
      G.bust = function () { savedToast('mob'); }; // angry mob
      lockProp(P, 'grabbers', 0); // no grab slowdown, never reaches the 3-grabber bust
    }

    // muting mid-clip silences it too, like the game's own sounds
    const sfx = at.sfx;
    if (sfx?.setMuted) {
      const origSetMuted = sfx.setMuted;
      sfx.setMuted = function (m) { if (m) stopAllSounds(); return origSetMuted.apply(this, arguments); };
    }

    if (CFG.invincible) watchMob(at);
    watchScore(at);
    setupFly(at);

    addMenuKeys();
    addPauseButton();

    log(`active — mode by ${CREDIT} ${CREDIT_URL}, game by ${GAME_CREDIT} ${GAME_CREDIT_URL}`, { ...CFG, speedTable: !!window.__BR_speed, crashTable: !!window.__BR_crash });
  }

  const wait = setInterval(() => {
    const at = window.__at;
    if (at?.P && at?.G) {
      clearInterval(wait);
      applyMods(at);
    }
  }, 100);
  setTimeout(() => {
    if (!window.__at) { clearInterval(wait); warn('window.__at never appeared — mods not applied'); }
  }, 30000);

  // --- Cheat keys (physical keys, so they work on any keyboard layout) ---
  //   F (hold) fly forward at limited height; release F to fly down to road
  //   Z        clear the mob        Shift+Z  auto-clear mob on/off
  //   K / Esc  end the run → newspaper with your ৳ score
  //   ] / [    speed up / down       P        pause / resume
  // Game keys are W A S D H M B R (Esc only on the newspaper and dialogs), so none of these collide.
  const hint = (text) => window.__at?.MSG?.show?.('hint', text, 2, 0);
  let autoMobTimer = null;

  // --- Fly Mode (Hold F): fly forward at a limited height using the rickshaw's 3D rocket thrusters ---
  const FLY_MAX_ALT = 3.8; // limited height: clears cars, buses, barriers & holes while staying on the road
  let flyOn = false;
  let flyAlt = 0;
  let flySoundUntil = 0;
  let flySoundPlayed = false;

  function setFly(on) {
    const at = window.__at;
    if (!at?.P || !at?.G) return;
    if (on && at.G.state !== 'play') return;
    if (flyOn === !!on) return;
    flyOn = !!on;
    window.__BR_flying = flyOn;
    if (flyOn) {
      at.P.jump = null;
      // Only play takeoff sound once per flight (and never overlap if clip is still playing)
      if (!flySoundPlayed && performance.now() >= flySoundUntil) {
        flySoundPlayed = true;
        const durMs = (at.sfx?.clips?.technologia?.duration || 4.2) * 1000;
        flySoundUntil = performance.now() + durMs;
        at.sfx?.rocket?.(1.0);
        at.sfx?.technologia?.();
        at.PLAYER?.smoke?.(8, 0.9, 2.2, 0.35);
      }
    }
  }

  function setupFly(at) {
    const { P, G, PLAYER } = at;
    if (!PLAYER) return;

    // Prevent road jump-pads from triggering jump() and replaying rocket/technologia while flying
    if (PLAYER.jump) {
      const origJump = PLAYER.jump;
      PLAYER.jump = function () {
        if (flyOn || flyAlt > 0.05) return false;
        return origJump.apply(this, arguments);
      };
    }

    // Prevent technologia clip from ever overlapping itself
    if (at.sfx?.technologia) {
      const origTech = at.sfx.technologia;
      let techPlayingUntil = 0;
      at.sfx.technologia = function () {
        const now = performance.now();
        if (now < techPlayingUntil) return;
        const durMs = (this.clips?.technologia?.duration || 4.2) * 1000;
        techPlayingUntil = now + durMs;
        return origTech.apply(this, arguments);
      };
    }

    if (PLAYER.collideProps) {
      const origProps = PLAYER.collideProps;
      PLAYER.collideProps = function () {
        if ((flyOn || flyAlt > 0.5) && P.air > 1.8) return;
        return origProps.apply(this, arguments);
      };
    }

    if (PLAYER.collideTraffic) {
      const origTraffic = PLAYER.collideTraffic;
      PLAYER.collideTraffic = function () {
        if ((flyOn || flyAlt > 0.5) && P.air > 2.0) return;
        return origTraffic.apply(this, arguments);
      };
    }

    if (PLAYER.reset) {
      const origReset = PLAYER.reset;
      PLAYER.reset = function () {
        flyOn = false;
        flyAlt = 0;
        flySoundPlayed = false;
        window.__BR_flying = false;
        return origReset.apply(this, arguments);
      };
    }

    if (PLAYER.update) {
      const origUpdate = PLAYER.update;
      PLAYER.update = function (dt, input) {
        if (flyOn || flyAlt > 0.05) {
          P.jump = null;
        }
        // Holding F forces forward-only throttle (no reverse/brake) while keeping left/right steering
        const effInput = (flyOn && G.state === 'play' && P.alive && input)
          ? { ...input, gas: 1, boost: 1, brake: 0 }
          : input;
        if (flyOn && P.v < 0) P.v = 0;

        const res = origUpdate.call(this, dt, effInput);
        if (G.state !== 'play' || !P.alive) return res;

        if (flyOn) {
          flyAlt += (FLY_MAX_ALT - flyAlt) * Math.min(1, dt * 7);
          const bob = Math.sin(performance.now() / 280) * 0.12;
          P.air = Math.min(FLY_MAX_ALT + 0.15, Math.max(0.4, flyAlt + bob));
          P.onFoot = false;
          const targetPitch = flyAlt < FLY_MAX_ALT - 0.4 ? -0.14 : 0.06;
          P.pitch += (targetPitch - P.pitch) * Math.min(1, dt * 8);
        } else if (flyAlt > 0.05) {
          flyAlt = Math.max(0, flyAlt - 14 * dt);
          P.air = flyAlt;
          P.pitch += (0.14 - P.pitch) * Math.min(1, dt * 8);
          if (flyAlt <= 0.05) {
            flyAlt = 0;
            flySoundPlayed = false;
            P.air = 0;
            P.pitch = 0;
            P.bumpY = 0.18;
            at.sfx?.thud?.(P.x, P.z, 0.65);
            PLAYER.smoke?.(6, 0.8, 2.2, 0.3);
          }
        }
        return res;
      };
    }

    // Light up the rickshaw's built-in 4 plasma rocket thrusters and smoke trail while flying
    if (PLAYER.rocket) {
      const origRocket = PLAYER.rocket;
      PLAYER.rocket = function (dt, elapsed) {
        if ((flyOn || flyAlt > 0.3) && P.alive && !P.jump) {
          P.jump = { y: P.air, vy: 0, apex: false };
          try {
            return origRocket.call(this, dt, elapsed);
          } finally {
            P.jump = null;
          }
        }
        return origRocket.apply(this, arguments);
      };
    }
  }

  function clearMob() {
    const people = window.__at?.PEOPLE;
    if (!people?.settle) return false;
    const had = people.mob;
    people.settle();
    return had;
  }

  // --- Pause: the game's own freeze switch (what it uses for hidden tabs) stops update + render ---
  let paused = false;
  let pauseBtn = null;
  let pauseEl = null;
  const PAUSE_ICON = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 5h3.5v14H7zM13.5 5H17v14h-3.5z" fill="currentColor"/></svg>';
  const PLAY_ICON = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5v14l11-7z" fill="currentColor"/></svg>';

  function setPaused(on) {
    const at = window.__at;
    if (!at?.freeze || paused === on || (on && at.G?.state !== 'play')) return;
    paused = on;
    at.freeze(on);
    if (on) { at.sfx?.suspend?.(); stopAllSounds(); } else if (!document.hidden) at.sfx?.resume?.();
    pauseOverlay().classList.toggle('show', on);
    if (pauseBtn) {
      pauseBtn.innerHTML = on ? PLAY_ICON : PAUSE_ICON;
      pauseBtn.setAttribute('aria-label', on ? 'আবার চালান' : 'পজ');
    }
  }

  function pauseOverlay() {
    if (pauseEl) return pauseEl;
    const style = document.createElement('style');
    style.textContent = `
      #br-pause{position:fixed;inset:0;z-index:99998;display:none;align-items:center;justify-content:center;flex-direction:column;
        background:rgba(0,0,0,.45);cursor:pointer;font-family:"Baloo Da 2","Anek Bangla",sans-serif;text-align:center}
      #br-pause.show{display:flex}
      #br-pause b{padding:12px 30px 8px;border-radius:16px;background:#ffd400;border:4px solid #c8102e;box-shadow:0 6px 0 #7a0a1c;
        font-size:clamp(30px,6vw,52px);font-weight:800;color:#c8102e;text-shadow:2px 2px 0 #fff}
      #br-pause span{margin-top:12px;color:#fff;font-size:clamp(14px,2.4vw,18px);font-weight:700}
      #br-pause-btn{display:grid;place-items:center;justify-self:end;width:44px;height:44px;padding:0;margin:0;border-radius:50%;
        background:rgba(12,10,8,.6);border:1.5px solid rgba(255,255,255,.5);color:#fff;cursor:pointer;pointer-events:auto}
      #br-pause-btn svg{width:22px;height:22px}`;
    document.head.appendChild(style);
    pauseEl = document.createElement('div');
    pauseEl.id = 'br-pause';
    pauseEl.innerHTML = '<b>⏸ বিরতি</b><span>চালাতে P চাপুন বা যেকোনো জায়গায় ট্যাপ করুন</span>';
    pauseEl.addEventListener('pointerdown', (e) => { e.stopPropagation(); e.preventDefault(); setPaused(false); });
    document.body.appendChild(pauseEl);
    return pauseEl;
  }

  // sits under the game's sound button, so it shows and hides with the in-run HUD
  function addPauseButton() {
    const mute = document.getElementById('muteBtn');
    if (!mute || pauseBtn) return;
    pauseOverlay(); // also injects the button's styles
    pauseBtn = document.createElement('button');
    pauseBtn.id = 'br-pause-btn';
    pauseBtn.type = 'button';
    pauseBtn.title = 'পজ (P)';
    pauseBtn.setAttribute('aria-label', 'পজ');
    pauseBtn.innerHTML = PAUSE_ICON;
    // pointerdown so touch steering never sees it; the click is swallowed too
    pauseBtn.addEventListener('pointerdown', (e) => { e.stopPropagation(); e.preventDefault(); setPaused(!paused); });
    pauseBtn.addEventListener('click', (e) => e.stopPropagation());
    mute.after(pauseBtn);
  }

  // the game unfreezes itself when the tab comes back; stay paused if the player paused
  document.addEventListener('visibilitychange', () => {
    if (paused && !document.hidden) setTimeout(() => { window.__at?.freeze?.(true); window.__at?.sfx?.suspend?.(); });
  });

  const CHEATS = {
    toggleFly() {
      setFly(!flyOn);
    },
    // end the run on purpose (you're unkillable otherwise): normal bus-death ending + newspaper
    endRun() {
      const G = window.__at?.G;
      if (G?.state !== 'play' || !origKill) return;
      setPaused(false);
      flyOn = false;
      flyAlt = 0;
      window.__BR_flying = false;
      origKill.call(G, 'bus');
      // Skip the 4.8s slow-motion death delay so the newspaper & score submission happen right away
      G.deathT = Math.min(G.deathT || 0.8, 0.8);
      G.slowT = 0;
      playEndSound();
    },
    clearMob() {
      const had = clearMob();
      hint(had ? `🙏 মব শান্ত (${had} জন)` : '🙏 কোনো মব নেই');
    },
    autoMob() {
      if (autoMobTimer) {
        clearInterval(autoMobTimer);
        autoMobTimer = null;
        hint('👥 অটো মব-ক্লিয়ার বন্ধ');
      } else {
        autoMobTimer = setInterval(() => { if (window.__at?.PEOPLE?.mob) clearMob(); }, 250);
        hint('👥 অটো মব-ক্লিয়ার চালু');
      }
    },
  };

  window.addEventListener('keydown', (e) => {
    if (e.target?.closest?.('input,textarea')) return;
    if (e.code === 'KeyF' && !e.ctrlKey && !e.metaKey && !e.altKey) {
      setFly(true);
      return;
    }

    if (e.repeat || e.ctrlKey || e.metaKey || e.altKey) return;
    if (e.code === 'KeyZ') e.shiftKey ? CHEATS.autoMob() : CHEATS.clearMob();
    else if (e.code === 'KeyK') CHEATS.endRun();
    else if (e.code === 'KeyP') setPaused(!paused);
    else if (e.code === 'Escape' && window.__at?.G?.state === 'play') {
      // the game's own Esc on the newspaper means "home"; keep this press from reaching it
      e.preventDefault();
      e.stopImmediatePropagation();
      CHEATS.endRun();
    }
    else if (e.code === 'BracketRight') setSpeed(CFG.speedMult + 0.5);
    else if (e.code === 'BracketLeft') setSpeed(CFG.speedMult - 0.5);
  });

  window.addEventListener('keyup', (e) => {
    if (e.code === 'KeyF') setFly(false);
  });
  window.addEventListener('blur', () => { setFly(false); });

  window.BR_MOD = { CFG, setSpeed, CHEATS };

  // bongoboltu.mp3, inlined because the page can't read local files
  const BONGOBOLTU_MP3 = 'data:audio/mpeg;base64,';
  // zodi-rat.mp3 (64 kbps mono), played only when the run is ended manually
  const ZODI_RAT_MP3 = 'data:audio/mpeg;base64,';
})();
